   135	/*
   136	 * Go through the whole list, stopping if you find a match.  Process all
   137	 * the continuations of that match before returning.
   138	 *
   139	 * We support multi-level continuations:
   140	 *
   141	 *      At any time when processing a successful top-level match, there is a
   142	 *      current continuation level; it represents the level of the last
   143	 *      successfully matched continuation.
   144	 *
   145	 *      Continuations above that level are skipped as, if we see one, it
   146	 *      means that the continuation that controls them - i.e, the
   147	 *      lower-level continuation preceding them - failed to match.
   148	 *
   149	 *      Continuations below that level are processed as, if we see one,
   150	 *      it means we've finished processing or skipping higher-level
   151	 *      continuations under the control of a successful or unsuccessful
   152	 *      lower-level continuation, and are now seeing the next lower-level
   153	 *      continuation and should process it.  The current continuation
   154	 *      level reverts to the level of the one we're seeing.
   155	 *
   156	 *      Continuations at the current level are processed as, if we see
   157	 *      one, there's no lower-level continuation that may have failed.
   158	 *
   159	 *      If a continuation matches, we bump the current continuation level
   160	 *      so that higher-level continuations are processed.
   161	 */
   162	private int
   163	match(struct magic_set *ms, struct magic *magic, uint32_t nmagic,
   164	    const unsigned char *s, size_t nbytes, size_t offset, int mode, int text,
   165	    int flip, uint16_t *indir_count, uint16_t *name_count,
   166	    int *printed_something, int *need_separator, int *returnval)
   167	{
   168	        uint32_t magindex = 0;
   169	        unsigned int cont_level = 0;
   170	        int returnvalv = 0, e; /* if a match is found it is set to 1*/
   171	        int firstline = 1; /* a flag to print X\n  X\n- X */
   172	        int print = (ms->flags & MAGIC_NODESC) == 0;
   173	
   174	        if (returnval == NULL)
   175	                returnval = &returnvalv;
   176	
   177	        if (file_check_mem(ms, cont_level) == -1)
   178	                return -1;
   179	
   180	        for (magindex = 0; magindex < nmagic; magindex++) {
   181	                int flush = 0;
   182	                struct magic *m = &magic[magindex];
   183	
   184	                if (m->type != FILE_NAME)
   185	                if ((IS_STRING(m->type) &&
   186	#define FLT (STRING_BINTEST | STRING_TEXTTEST)
   187	                     ((text && (m->str_flags & FLT) == STRING_BINTEST) ||
   188	                      (!text && (m->str_flags & FLT) == STRING_TEXTTEST))) ||
   189	                    (m->flag & mode) != mode) {
   190	flush:
   191	                        /* Skip sub-tests */
   192	                        while (magindex < nmagic - 1 &&
   193	                            magic[magindex + 1].cont_level != 0)
   194	                                magindex++;
   195	                        continue; /* Skip to next top-level test*/
   196	                }
   197	
   198	                ms->offset = m->offset;
   199	                ms->line = m->lineno;
   200	
   201	                /* if main entry matches, print it... */
   202	                switch (mget(ms, s, m, nbytes, offset, cont_level, mode, text,
   203	                    flip, indir_count, name_count,
   204	                    printed_something, need_separator, returnval)) {
   205	                case -1:
   206	                        return -1;
   207	                case 0:
   208	                        flush = m->reln != '!';
   209	                        break;
   210	                default:
   211	                        if (m->type == FILE_INDIRECT)
   212	                                *returnval = 1;
   213	
   214	                        switch (magiccheck(ms, m)) {
   215	                        case -1:
   216	                                return -1;
   217	                        case 0:
   218	                                flush++;
   219	                                break;
   220	                        default:
   221	                                flush = 0;
   222	                                break;
   223	                        }
   224	                        break;
   225	                }
   226	                if (flush) {
   227	                        /*
   228	                         * main entry didn't match,
   229	                         * flush its continuations
   230	                         */
   231	                        goto flush;
   232	                }
   233	
   234	                if ((e = handle_annotation(ms, m, firstline)) != 0) {
   235	                        *need_separator = 1;
   236	                        *printed_something = 1;
   237	                        *returnval = 1;
   238	                        return e;
   239	                }
   240	
   241	                /*
   242	                 * If we are going to print something, we'll need to print
   243	                 * a blank before we print something else.
   244	                 */
   245	                if (*m->desc) {
   246	                        *need_separator = 1;
   247	                        *printed_something = 1;
   248	                        if (print_sep(ms, firstline) == -1)
   249	                                return -1;
   250	                }
   251	
   252	
   253	                if (print && mprint(ms, m) == -1)
   254	                        return -1;
   255	
   256	                switch (moffset(ms, m, nbytes, &ms->c.li[cont_level].off)) {
   257	                case -1:
   258	                case 0:
   259	                        goto flush;
   260	                default:
   261	                        break;
   262	                }
   263	
   264	                /* and any continuations that match */
   265	                if (file_check_mem(ms, ++cont_level) == -1)
   266	                        return -1;
   267	
   268	                while (magindex + 1 < nmagic &&
   269	                    magic[magindex + 1].cont_level != 0) {
   270	                        m = &magic[++magindex];
   271	                        ms->line = m->lineno; /* for messages */
   272	
   273	                        if (cont_level < m->cont_level)
   274	                                continue;
   275	                        if (cont_level > m->cont_level) {
   276	                                /*
   277	                                 * We're at the end of the level
   278	                                 * "cont_level" continuations.
   279	                                 */
   280	                                cont_level = m->cont_level;
   281	                        }
   282	                        ms->offset = m->offset;
   283	                        if (m->flag & OFFADD) {
   284	                                ms->offset +=
   285	                                    ms->c.li[cont_level - 1].off;
   286	                        }
   287	
   288	#ifdef ENABLE_CONDITIONALS
   289	                        if (m->cond == COND_ELSE ||
   290	                            m->cond == COND_ELIF) {
   291	                                if (ms->c.li[cont_level].last_match == 1)
   292	                                        continue;
   293	                        }
   294	#endif
   295	                        switch (mget(ms, s, m, nbytes, offset, cont_level, mode,
   296	                            text, flip, indir_count, name_count,
   297	                            printed_something, need_separator, returnval)) {
   298	                        case -1:
   299	                                return -1;
   300	                        case 0:
   301	                                if (m->reln != '!')
   302	                                        continue;
   303	                                flush = 1;
   304	                                break;
   305	                        default:
   306	                                if (m->type == FILE_INDIRECT)
   307	                                        *returnval = 1;
   308	                                flush = 0;
   309	                                break;
   310	                        }
   311	
   312	                        switch (flush ? 1 : magiccheck(ms, m)) {
   313	                        case -1:
   314	                                return -1;
   315	                        case 0:
   316	#ifdef ENABLE_CONDITIONALS
   317	                                ms->c.li[cont_level].last_match = 0;
   318	#endif
   319	                                break;
   320	                        default:
   321	#ifdef ENABLE_CONDITIONALS
   322	                                ms->c.li[cont_level].last_match = 1;
   323	#endif
   324	                                if (m->type == FILE_CLEAR)
   325	                                        ms->c.li[cont_level].got_match = 0;
   326	                                else if (ms->c.li[cont_level].got_match) {
   327	                                        if (m->type == FILE_DEFAULT)
   328	                                                break;
   329	                                } else
   330	                                        ms->c.li[cont_level].got_match = 1;
   331	
   332	                                if ((e = handle_annotation(ms, m, firstline)) != 0) {
   333	                                        *need_separator = 1;
   334	                                        *printed_something = 1;
   335	                                        *returnval = 1;
   336	                                        return e;
   337	                                }
   338	                                /*
   339	                                 * If we are going to print something,
   340	                                 * make sure that we have a separator first.
   341	                                 */
   342	                                if (*m->desc) {
   343	                                        if (!*printed_something) {
   344	                                                *printed_something = 1;
   345	                                                if (print_sep(ms, firstline)
   346	                                                    == -1)
   347	                                                        return -1;
   348	                                        }
   349	                                }
   350	                                /*
   351	                                 * This continuation matched.  Print
   352	                                 * its message, with a blank before it
   353	                                 * if the previous item printed and
   354	                                 * this item isn't empty.
   355	                                 */
   356	                                /* space if previous printed */
   357	                                if (*need_separator
   358	                                    && ((m->flag & NOSPACE) == 0)
   359	                                    && *m->desc) {
   360	                                        if (print &&
   361	                                            file_printf(ms, " ") == -1)
   362	                                                return -1;
   363	                                        *need_separator = 0;
   364	                                }
   365	                                if (print && mprint(ms, m) == -1)
   366	                                        return -1;
   367	
   368	                                switch (moffset(ms, m, nbytes,
   369	                                    &ms->c.li[cont_level].off)) {
   370	                                case -1:
   371	                                case 0:
   372	                                        flush = 1;
   373	                                        break;
   374	                                default:
   375	                                        break;
   376	                                }
   377	
   378	                                if (*m->desc)
   379	                                        *need_separator = 1;
   380	
   381	                                /*
   382	                                 * If we see any continuations
   383	                                 * at a higher level,
   384	                                 * process them.
   385	                                 */
   386	                                if (file_check_mem(ms, ++cont_level) == -1)
   387	                                        return -1;
   388	                                break;
   389	                        }
   390	                }
   391	                if (*printed_something) {
   392	                        firstline = 0;
   393	                        if (print)
   394	                                *returnval = 1;
   395	                }
   396	                if ((ms->flags & MAGIC_CONTINUE) == 0 && *printed_something) {
   397	                        return *returnval; /* don't keep searching */
   398	                }
   399	                cont_level = 0;
   400	        }
   401	        return *returnval;  /* This is hit if -k is set or there is no match */
   402	}
