   404	private int
   405	check_fmt(struct magic_set *ms, struct magic *m)
   406	{
   407	        file_regex_t rx;
   408	        int rc, rv = -1;
   409	
   410	        if (strchr(m->desc, '%') == NULL)
   411	                return 0;
   412	
   413	        rc = file_regcomp(&rx, "%[-0-9\\.]*s", REG_EXTENDED|REG_NOSUB);
   414	        if (rc) {
   415	                file_regerror(&rx, rc, ms);
   416	        } else {
   417	                rc = file_regexec(&rx, m->desc, 0, 0, 0);
   418	                rv = !rc;
   419	        }
   420	        file_regfree(&rx);
   421	        return rv;
   422	}
