   427	char *
   428	strndup(const char *str, size_t n)
   429	{
   430	        size_t len;
   431	        char *copy;
   432	
   433	        for (len = 0; len < n && str[len]; len++)
   434	                continue;
   435	        if ((copy = malloc(len + 1)) == NULL)
   436	                return NULL;
   437	        (void)memcpy(copy, str, len);
   438	        copy[len] = '\0';
   439	        return copy;
   440	}
