   443	private int32_t
   444	mprint(struct magic_set *ms, struct magic *m)
   445	{
   446	        uint64_t v;
   447	        float vf;
   448	        double vd;
   449	        int64_t t = 0;
   450	        char buf[128], tbuf[26], sbuf[512];
   451	        union VALUETYPE *p = &ms->ms_value;
   452	
   453	        switch (m->type) {
   454	        case FILE_BYTE:
   455	                v = file_signextend(ms, m, (uint64_t)p->b);
   456	                switch (check_fmt(ms, m)) {
   457	                case -1:
   458	                        return -1;
   459	                case 1:
   460	                        (void)snprintf(buf, sizeof(buf), "%d",
   461	                            (unsigned char)v);
   462	                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
   463	                                return -1;
   464	                        break;
   465	                default:
   466	                        if (file_printf(ms, F(ms, m, "%d"),
   467	                            (unsigned char) v) == -1)
   468	                                return -1;
   469	                        break;
   470	                }
   471	                t = ms->offset + sizeof(char);
   472	                break;
   473	
   474	        case FILE_SHORT:
   475	        case FILE_BESHORT:
   476	        case FILE_LESHORT:
   477	                v = file_signextend(ms, m, (uint64_t)p->h);
   478	                switch (check_fmt(ms, m)) {
   479	                case -1:
   480	                        return -1;
   481	                case 1:
   482	                        (void)snprintf(buf, sizeof(buf), "%u",
   483	                            (unsigned short)v);
   484	                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
   485	                                return -1;
   486	                        break;
   487	                default:
   488	                        if (file_printf(ms, F(ms, m, "%u"),
   489	                            (unsigned short) v) == -1)
   490	                                return -1;
   491	                        break;
   492	                }
   493	                t = ms->offset + sizeof(short);
   494	                break;
   495	
   496	        case FILE_LONG:
   497	        case FILE_BELONG:
   498	        case FILE_LELONG:
   499	        case FILE_MELONG:
   500	                v = file_signextend(ms, m, (uint64_t)p->l);
   501	                switch (check_fmt(ms, m)) {
   502	                case -1:
   503	                        return -1;
   504	                case 1:
   505	                        (void)snprintf(buf, sizeof(buf), "%u", (uint32_t) v);
   506	                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
   507	                                return -1;
   508	                        break;
   509	                default:
   510	                        if (file_printf(ms, F(ms, m, "%u"), (uint32_t) v) == -1)
   511	                                return -1;
   512	                        break;
   513	                }
   514	                t = ms->offset + sizeof(int32_t);
   515	                break;
   516	
   517	        case FILE_QUAD:
   518	        case FILE_BEQUAD:
   519	        case FILE_LEQUAD:
   520	                v = file_signextend(ms, m, p->q);
   521	                switch (check_fmt(ms, m)) {
   522	                case -1:
   523	                        return -1;
   524	                case 1:
   525	                        (void)snprintf(buf, sizeof(buf), "%" INT64_T_FORMAT "u",
   526	                            (unsigned long long)v);
   527	                        if (file_printf(ms, F(ms, m, "%s"), buf) == -1)
   528	                                return -1;
   529	                        break;
   530	                default:
   531	                        if (file_printf(ms, F(ms, m, "%" INT64_T_FORMAT "u"),
   532	                            (unsigned long long) v) == -1)
   533	                                return -1;
   534	                        break;
   535	                }
   536	                t = ms->offset + sizeof(int64_t);
   537	                break;
   538	
   539	        case FILE_STRING:
   540	        case FILE_PSTRING:
   541	        case FILE_BESTRING16:
   542	        case FILE_LESTRING16:
   543	                if (m->reln == '=' || m->reln == '!') {
   544	                        if (file_printf(ms, F(ms, m, "%s"), 
   545	                            file_printable(sbuf, sizeof(sbuf), m->value.s))
   546	                            == -1)
   547	                                return -1;
   548	                        t = ms->offset + m->vallen;
   549	                }
   550	                else {
   551	                        char *str = p->s;
   552	
   553	                        /* compute t before we mangle the string? */
   554	                        t = ms->offset + strlen(str);
   555	
   556	                        if (*m->value.s == '\0')
   557	                                str[strcspn(str, "\r\n")] = '\0';
   558	
